import React from "react";

function BudgetLimits({
  incomeCategory,
  questionnaire,
  spendingPriorities,
  budgetLimits,
  setBudgetLimits,
  onNext
}) {
  const eligibleCategories = Object.keys(spendingPriorities).filter(
    (cat) => spendingPriorities[cat] >= 3
  );

  const handleChange = (category, value) => {
    setBudgetLimits({
      ...budgetLimits,
      [category]: value
    });
  };

  const saveToDatabase = async () => {
    try {
      const response = await fetch("http://localhost:5000/save-budget", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          incomeCategory,
          questionnaire,
          spendingPriorities,
          budgetLimits
        })
      });

      const result = await response.json();
      console.log(result);
      alert("Data saved successfully!");
    } catch (error) {
      console.error(error);
      alert("Server connection failed");
    }
  };

  const handleNext = async () => {
    await saveToDatabase();
    onNext();
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">
        <h2 className="questionnaire-title">Set Budget Limits</h2>

        {eligibleCategories.map((cat) => (
          <div className="form-group" key={cat}>
            <label className="form-label">{cat}</label>
            <input
              className="form-input"
              type="number"
              placeholder="Enter budget"
              value={budgetLimits[cat] || ""}
              onChange={(e) => handleChange(cat, e.target.value)}
            />
          </div>
        ))}

        <button className="next-button" onClick={handleNext}>
          Continue
        </button>
      </div>
    </div>
  );
}

export default BudgetLimits;
